import{_ as r}from"./chunks/1026c18fabfe60f1e48d.BwdGMXRt.js";import{_ as a,C as l,o,c as i,j as e,a as n,E as s,a6 as h}from"./chunks/framework.CnPv4DE1.js";const T=JSON.parse('{"title":"价值创作者（聪明人的互联网新职业路径）","description":"","frontmatter":{"title":"价值创作者（聪明人的互联网新职业路径）","originalTitle":"The Value Creator (A New Internet Career Path For Intelligent People)","date":"2023-07-08","originalUrl":"https://thedankoe.com/letters/the-value-creator-a-new-internet-career-path-for-intelligent-people/","minutes":17,"sourceHash":"cd09cb0801352c9c6143f7a3d2e393913e05c0847bb5f573d514a63dc12d4972","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-value-creator-a-new-internet-career-path-for-intelligent-people/"}]]},"headers":[],"relativePath":"letters/the-value-creator-a-new-internet-career-path-for-intelligent-people.md","filePath":"letters/the-value-creator-a-new-internet-career-path-for-intelligent-people.md"}'),c={name:"letters/the-value-creator-a-new-internet-career-path-for-intelligent-people.md"};function u(m,p,d,g,f,b){const t=l("ArticleMeta");return o(),i("div",null,[p[0]||(p[0]=e("h1",{id:"价值创作者-聪明人的互联网新职业路径",tabindex:"-1"},[n("价值创作者（聪明人的互联网新职业路径） "),e("a",{class:"header-anchor",href:"#价值创作者-聪明人的互联网新职业路径","aria-label":'Permalink to "价值创作者（聪明人的互联网新职业路径）"'},"​")],-1)),s(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/PhbJLu0RFHQ?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>雇主基于你的社交媒体来招聘。</p><p>创作者基于你的社交媒体来招聘。</p><p>品牌基于你的社交媒体来招聘。</p><p>客户基于你的社交媒体来雇佣你。</p><p>消费者基于你的社交媒体来购买。</p><p>社交媒体是现代生活的必需品。</p><p>它<em>就是</em>虚拟现实。</p><p>它<em>就是</em>数字社会。</p><p>它<em>就是</em>新经济。</p><p>没有一份公开的简历，你就向全球的机遇关上了大门。</p><p>大多数人仍然认为它只是“手机上的一个应用程序”。</p><p>然而，他们却在上面花费了生命中极大的一部分时间。</p><p>不断刷屏，而不是构建自己的未来。</p><p>一旦你看清了社交媒体的本质，一个新世界就会向你敞开。</p><p>你可以学到学校教不了你的技能。</p><p>你可以结交那些比你当地朋友做着更宏大事业的朋友。</p><p>你可以赚到不受薪水上限限制的钱。</p><p>你正处于数字文艺复兴的中心。</p><p>好好利用它。</p><h3 id="国家的衰落" tabindex="-1">国家的衰落 <a class="header-anchor" href="#国家的衰落" aria-label="Permalink to &quot;国家的衰落&quot;">​</a></h3><p>上周我正在读一篇关于《主权个人》（The Sovereign Individual）的 <a href="https://shortform.com/dan" target="_blank" rel="noreferrer">Shortform</a> 摘要。</p><p>我以前读过这本书，但我没有建立起一个重要的联系。</p><p>这本书的核心论点是：</p><ul><li>“国家”将分裂成数以百万计的“城邦”，甚至是具有主权国家地位的个人“领地”。</li><li>信息技术正在迅速发展，使资源能够被更多人获取。</li><li>这将改变社会结构，以及我们在政治和经济上相互联系的方式。</li><li>人们如何赚取最大利润的钱，会影响社会的进化。社会将围绕这些工作、职业或企业重塑自身。</li><li>创造一种新的赚钱方式，或使企业变得更<em>有利可图</em>，将促使社会做出适应以增加其财富。</li></ul><p>这本书预测了我过去一年一直在宣扬的内容。</p><p>即未来的工作就是玩耍。</p><p>即个人可以利用他们能获得的新技术来 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">发展一人企业</a>。</p><p>即一人企业模式可以实现每年100万到500万美元的收入，利润率高达90-95%，因此社会正在适应并反映出这一点。</p><p>即人人都是企业家，社交媒体是新社会，而个人品牌或创作者就是这个社会中的人。</p><p>每个人长大后都想当“YouTuber”是有原因的。虽然作为孩子这可能有些夸张，但人们能感受到一种自然而然的引力，驱使他们去做自己热爱的事情，并在过程中帮助他人。而大部分人口其实都有途径做到这一点（当然，也许不只是在YouTube上，但我们将看到技术和社交媒体继续朝着这个现实发展）。</p><p>进化反映了人类的渴望。</p><p>我们通过解决问题来实现那种渴望。</p><p>社交媒体解决了如此多问题，以至于我们尚未意识到它的真正影响。</p><p>创作者经济是一个去中心化的实体，由保持自身主权的品牌（或城邦）和创作者（或个人领地）组成。</p><p>如果你想参与人类进化的下一阶段，成为一名价值创作者就是答案。</p><h3 id="教育的重要性" tabindex="-1">教育的重要性 <a class="header-anchor" href="#教育的重要性" aria-label="Permalink to &quot;教育的重要性&quot;">​</a></h3><p>教育是创造价值的第一步。</p><p>如果你自己不成为一个有价值的人，你要如何创造出任何值得传播的东西？</p><p>是的，要想加入这个全新的、有利可图的经济体系，你需要对你的人生做点什么。没想到吧。</p><p>但是，传统教育根本不够用。</p><p>当前的学校系统恰如其名，只是一个系统。</p><p>一个把你塑造成劳动力的系统。</p><p>它教授的是在旧经济中打工所必需的服从和技能。</p><p>如果你想在新经济中赚钱，那么显然，你必须去寻找能教你如何赚钱的教育。</p><p>也就是来自那些已经<em>创造</em>了这些赚钱方式的品牌和创作者的课程、辅导和内容。</p><p>新工作正在接二连三地诞生。</p><p>就是那些婴儿潮一代会叫你去“找份正经工作”的职业。</p><p>每一个伟大的想法在成为常态之前，最初都被视作异端邪说。</p><p>这个领域仍在发展中。</p><p>这也解释了为什么许多人有被骗子坑过的糟糕经历。</p><p>如今这种骗子已经屈指可数了，特别是如果你具备一定的批判性思维能力来避开他们的话，但现在依然有大把值得学习的人。</p><p>为了适应不断变化的数字环境而进行终身自我教育，是在这个领域做生意的必需品。</p><p>教育塑造未来，因为它塑造人类行为。</p><p>教育拓展了你的视野，让你能在未知领域中发现机遇。</p><p>新的教育系统正在你眼前的互联网上建立起来。</p><p>设定一个目标。</p><p>寻找与你产生共鸣的创作者。</p><p>让自己沉浸在他们提供的信息中。</p><p>看着新的机遇在你的意识中显现。</p><p>像性命攸关一样去抓住它们行动。</p><h2 id="价值创作者的崛起" tabindex="-1">价值创作者的崛起 <a class="header-anchor" href="#价值创作者的崛起" aria-label="Permalink to &quot;价值创作者的崛起&quot;">​</a></h2><p>简而言之，价值创作者是这样一群人：</p><ul><li>用头脑赚钱，而不是用时间赚钱（这样他们就能保持 <a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">一人企业</a> 的模式，而不受收入上限的限制）。一个人的体力劳动无法规模化，但他们的创造能力可以。</li><li>研究他们痴迷的事物，并通过写作、视频及其他互联网内容来提炼他们的学识。</li><li>将知识和经验汇总，以数字产品（如果你愿意也可以是实体产品，但每个人都应该有某种形式的数字产品）的形式获取报酬。</li><li>极其注重教育他们的受众（而不是发发表情包、挑起争端或做其他类似的事情）。</li></ul><p>价值创作者是那些投身于自己兴趣的人，把探索兴趣作为毕生的事业，并以教育的形式提炼信息。</p><p>这就是我教授的一人企业模式。</p><p>创作社交媒体内容，以<em>你的名字</em>建立分发渠道。</p><p><a href="/letters/the-most-profitable-niche-is-you-how-to-create-your-niche">把你自身作为目标细分领域</a>。这就是你的销售对象，也是你创作内容的服务对象。</p><p>打造一个过去的你会用得上的 <a href="/letters/you-have-100000-of-knowledge-trapped-in-your-brain">教育产品或服务</a>（比如一门课程、教练辅导或家教服务）。</p><p>然后，当你达到你想赚的收入金额时（随着时间的推移，比如每年10万到300万美元），你就可以去打造你热爱的任何其他东西了。</p><p>通过成为你所热爱的技能和兴趣方面的专家，你主动创造了一个不断演进的教育系统。</p><p>政府无法也不愿去培育一套课程，为个人提供导致旧经济解体的工具。</p><h3 id="创作者是把玩思想的dj" tabindex="-1">创作者是把玩思想的DJ <a class="header-anchor" href="#创作者是把玩思想的dj" aria-label="Permalink to &quot;创作者是把玩思想的DJ&quot;">​</a></h3><p>DJ 播放音乐合集。</p><p>他们将自己的歌、别人很契合的歌混合在一起，并重新混音，为听众编织出一个<em>故事</em>。</p><p>技术的演进使电子DJ几乎能创造出他们想要的任何声音（仅受限于他们的创造力、思想和视角）。</p><p>凭借软件和技能，他们能将声音融合在一起，编辑音色，创作出吸引人们注意力的音乐。</p><p>创作者也不例外。</p><p>他们收集自己、别人的<em>思想</em>，以及他们最爱的变体。然后，他们用写作、演讲、营销和销售这些常青技能，将这些思想交织在一起。</p><p>随着时间推移，他们吸引了一批将注意力投入到这些思想中的受众。有了这些注意力，他们就能造福人类，并在做自己享受的事情中获得收入。</p><p><strong>创作者常犯的一个错误是：</strong></p><p>人们想一遍又一遍地听到他们最喜欢的艺术家的同样的声音。</p><p>如果我最喜欢的回响贝斯（dubstep）艺术家改做乡村音乐，他会流失90%的受众。</p><p>即便他试图创造一种新的回响贝斯风格，他也必须随着时间的推移，逐步引导受众的心智去欣赏它。就像你在一开始并不喜欢某种流派，直到你听得足够多（你追求的任何兴趣、目标或技能也是如此——热情来源于投入的精力）。</p><p>价值创作者也是如此。</p><p>如果你最喜欢的创作者停止制作让我发展到如今这个阶段的一人企业内容，我的受众就会流失。</p><p>你可以从我YouTube的播放量中看到这一点。只有少数几个宏大思想能给我带来吸引力。</p><p>作为创作者，你的工作就是找到这个角度，并永远把它用到极致。</p><p>注意我是如何将我所说的内容与我所有的兴趣进行“混音”的。从哲学到灵性，再到进化心理学。</p><p>发挥创意吧。</p><p>人们不在乎你是否在重复自己说过的话。</p><p>那些对你的作品感兴趣的人反而更喜欢这样。</p><p>你无法也不可能只读一遍就记住我在这封信里说的一切。内容创作就是编程。如果你想被记住，重复是必须的。</p><p>人们作为价值创作者失败的首要原因是：</p><p>他们害怕将自己推向市场（因为他们觉得自己不够独特）。</p><p>你有几双鞋？</p><p>同一个主题的书你会读几本？</p><p>同一个流派的艺术家你会听多少个？</p><p>写你想读的东西。</p><p>卖你想买的产品。</p><p>做你想看的视频。</p><p>将人们所需之物的你的独家版本推向市场。</p><p>只有这样，你的运气才会从0增加到1%。</p><h3 id="挖掘现实以提取价值" tabindex="-1">挖掘现实以提取价值 <a class="header-anchor" href="#挖掘现实以提取价值" aria-label="Permalink to &quot;挖掘现实以提取价值&quot;">​</a></h3><p>我们该如何开启价值创作者之旅？</p><p>从成为一名精神铁匠开始。</p><p>铁匠（至少在电子游戏里）会开采矿石，为他们的造物提供原料。他们会熔炼矿石并将其锻造成盔甲和武器。</p><p>创作者开采他们感兴趣的现实缝隙。</p><p>他们学习、研究并痴迷于特定主题，以收集可以分发给受众的价值。</p><p>凭借这些想法，他们打造出既能自己穿戴也能赠予他人的盔甲。</p><p>“盔甲”是指引你更好闯荡世界的视角。</p><p>就像一本书之所以能“改变你的人生”，是因为它赋予了你如何做出改变的认知。</p><p>“武器”是战斗的工具。</p><p>它们是人们可以据此采取行动以取得进步的实操建议、技巧和策略。</p><p>进步意味着挑战。一场个体必须在生活中克服的战斗。你传承你的经验教训，让别人能更高效地驾驭生活。</p><p>这就是你加速人类进化的方式：通过教育和世界观编程，去对抗社会强加的条件反射。</p><p><strong>1) 打造一个透镜</strong></p><p><img src="'+r+'" alt=""></p><p>在你收集信息、想法和价值的过程中，你需要一种方式来应用这些信息，用现实来检验它们。</p><p>你需要一个过滤器，让你的思想独具原创性。一个引导你创造力能量的容器。</p><p>换句话说，你需要建立一个与目标相一致的项目。一个能通向你愿景的项目。</p><p>为什么？</p><ul><li>因为领导者会吸引追随者。</li><li>这是你的细分领域和品牌。它是你构建一切阅读和写作内容的框架。</li><li>这就是你创造有价值事物的方式。价值帮助人们克服他们的问题或实现他们的目标。我们的目标是吸引有共同目标的人。</li></ul><p>这就是为什么两个人阅读同一本书、文章或内容，却能得出完全不同的想法。</p><p>如果你正努力改善健康，你的大脑就会像磁铁一样，吸引有助于此的想法。</p><p>努力改善财务状况的人，会从他们吸收的信息中记录下不同的想法。</p><p><strong>2) 追随好奇心去收集素材</strong></p><p>不要只是消费，要去研究。</p><p>最顶级的创作者并不会停止消费。相反，他们是为了学习和传播思想而消费。</p><p>单凭这种认知的转变，就能把你变成一台创意生成机。不要只是为了娱乐而刷互联网。要为了教育自己而刷。这比你想象的更强大。</p><p>你必须在传统教育体系（那个让你讨厌学习的体系）之外，重新爱上学习。</p><ul><li>阅读书籍、听播客、看博客文章和新闻通讯，让自己沉浸在与你目标一致的信息中。</li><li>准备一个笔记本、应用程序或想法开发系统，妥善保存你的点子。不，你记不住它们的。这一步绝对至关重要。我没有夸张。去做吧。</li><li>记下那些让你大脑多巴胺分泌的想法。那些死死抓住你注意力的想法。那些改变你视角、为你带来清晰度的想法。</li><li>思考你记下的想法的不同角度，以及它们如何应用于你的愿景、目标和生活中的问题。</li></ul><p><em>这就是你要在内容中写的东西。</em></p><p><em>不要将自己局限在特定主题中（尽管把它们写出来是件好事，这样你就有东西可以去研究并从中收集想法）__。</em></p><p><em>你在传播与某个目标一致的思想。</em></p><p><em>这些思想属于什么主题并不重要，因为很可能它们只属于“你”这个主题。这就是你让内容保持原创的方式。</em></p><p>如果你不知道该学什么，去读读 <a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">一人企业模式2.0信件 (The One Person Business Model 2.0 letter)</a>。</p><p>如果你想要提供明确步骤和策略的课程，去看看 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时作家 (2 Hour Writer)</a> 或 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学 (Digital Economics)</a>。</p><p><strong>3) 打造盔甲与武器</strong></p><p>你收集的想法会开始塑造你的世界观、基础视角和身份认同。</p><p>通过给自己的大脑编程，你的行动也会自然跟上。</p><p>编程就是这样运作的。</p><p>即使你很懒，面对明知存在的机会却不采取行动的痛苦，也会超过你一生无所事事的痛苦。</p><p><strong>打造盔甲：</strong> 赋予人们朝着目标前进的想法、动力和灵感。这能塑造他们的视角和身份。他们可以在生活中更快乐并实现目标。</p><p><strong>打造武器：</strong> 提供可执行的步骤、解决方案和建议</p><p>写作、演讲、营销和销售，是你将思想转化为有影响力作品的渠道。</p><p>然后，你在社交媒体平台上分发它们，在数字社会中建立一个社区。</p><h2 id="将你大脑的创造力变现" tabindex="-1">将你大脑的创造力变现 <a class="header-anchor" href="#将你大脑的创造力变现" aria-label="Permalink to &quot;将你大脑的创造力变现&quot;">​</a></h2><p>我们正在摆脱用肤浅的承诺和姣好的外貌来建立受众的方式。</p><p>健康产业变得不再健康，因为他们的收入依赖于他们的外貌。</p><p>而且，这为男性和女性的体型制造了糟糕的标准，导致了心理和精神健康的匮乏。</p><p>我再说一遍，价值创造才是答案。</p><p>健身网红（那些无法将智力或创造力变现的人）不得不维持次优的体脂水平和不健康的习惯。</p><p>如果不这么做，他们的收入就会减少。我在许多播客和YouTube视频中，多次听到行业内的教练这么说。</p><p>商业必须是可持续且健康的。</p><p>将你的头脑、智力或创造力变现是拥有无限潜力的。</p><p>以下是开始的方法，但首先，我们来解决一些限制性信念。</p><p>没错，这只是一些信念而已。这是你的大脑为了逃避你想采取的行动而使出的伎俩。</p><p><strong>你可以建立起一批受众或读者群。</strong></p><p>社交媒体上的每个人都关注了300到1000多人。创作者也不例外。只要你懂自己在干嘛，这数量足以赚取一份全职收入了。</p><p>获得更多粉丝既是意外收获，对于读到这篇文章的大多数人来说，也是完全可以实现的（你属于人类中了解到这条工作路线的那0.5%）。</p><p><strong>市场并没有饱和。</strong></p><p>它看起来饱和，只是因为你把自己局限在关注那300到1000个都在谈论你感兴趣话题的人里。</p><p>实际上，它完全没饱和，你甚至能在那个细分领域里把大多数创作者远远甩在身后。</p><p>配合 <a href="/letters/niche-down-is-terrible-advice-for-smart-people">我“向下细分”的方法</a> 一起使用，你就稳操胜券了。</p><h3 id="简化复杂的主题" tabindex="-1">简化复杂的主题 <a class="header-anchor" href="#简化复杂的主题" aria-label="Permalink to &quot;简化复杂的主题&quot;">​</a></h3><p>如果我们生活在信息时代……</p><p>而普通人感到不堪重负、焦虑和迷茫……</p><p>而教育塑造了继续去创造更美好未来的个体……</p><p>那么价值创造，就是梳理脉络、理清头绪（sense-making）。</p><p>你的工作是理清你的人生和这个世界，为他人应该采取的行动带来清晰度。也就是那些追随你的愿景并想将其变为现实的人。</p><p>这需要时间和行动。</p><p>如果你的作品从来没有被人看到过，你就不会知道它们是否有价值。</p><p>你必须发布。你必须获取数据。你必须把读者吸引到你的作品中来，因为如果不这样做，这便是你无法提供价值的第一个迹象。或者你只是不知道怎么玩这场游戏。</p><p>营销和销售需要人。你需要把你的作品放到市场面前。</p><p>如果你不努力把你的内容放到人们面前，你就不会知道你的想法是否有价值。</p><p>如果你把内容放到了人们面前，但效果不好，那它就是没有价值。你需要写得更好。</p><p>如果你不努力把你的产品放到人们面前，你就赚不到钱。</p><p>如果你把产品放到了人们面前，却没有买单，说明你的产品没被认为是有价值的。你需要卖得更好。</p><p>这里的关键词是<em>认为</em>（感知）。</p><p>营销和销售就是感知。</p><p>你必须以一种能引起你目标身份群体共鸣的方式来写作、演讲、营销和销售。</p><p>一个娇滴滴的山谷女孩不会对肌肉无脑男的健美建议产生共鸣。</p><p>一个全职主妇（可能）也不会对关于商业的哲学冥想产生共鸣。</p><p>你的语言决定了你会吸引谁。</p><p>当你不再被自己的思绪干扰，把事情想通透时，一切都变得如此简单。</p><p>随着时间的推移建立受众群体，正是你减少“将内容和产品推向人群所需的体力活”的方法。</p><p>好了，我们要从哪里开始？</p><p><strong>1) 从写作开始</strong></p><p>如果你想获得成功，写作会迫使你用写作技巧、销售和说服力来补充你的学习。</p><p>它可以厘清你的思绪。</p><p>它可以让你表达得更清晰。</p><p>它可以被重新制作成任何其他媒介（演讲、视频或视觉素材）。</p><p>它也是一项无缝的、要求不高的、能撬动杠杆的任务，你可以把它安排在每天早上的第一个时间块里。</p><p>因此，我们优先考虑在写作平台上实现增长和内容创作。</p><p><strong>从一份新闻通讯（Newsletter）开始</strong></p><p>深度是将你与肤浅市场区分开来的关键。</p><p>不，你不需要订阅者。你也可以把它当成博客文章上传，用它来写引流品或产品模块，或者像我一样把它作为YouTube视频脚本。</p><p>订阅者自然会来的。</p><p><strong>将复杂性浓缩为推文（或帖子）</strong></p><p>在我看来，Twitter曾经是一个被严重低估的写作平台。</p><p>现在也是，但Instagram新推出的Threads应用让我想起了起步阶段的Twitter。</p><p>那里有一片充满机会的天地，而且社区氛围极佳。</p><p>Threads拥有巨大的潜力。</p><p>为什么？</p><ul><li>你想发多少贴就发多少贴（在你将想法发布到其他平台之前进行测试）。</li><li>它是基于文字的，这意味着你不需要成为一个住在泰国、在海滩上喝着椰子汁的满分模特。</li><li>它像一个论坛，你可以更快速地在你喜欢的账号的回复中找到志同道合的人。</li><li>转推或转发按钮是一个低摩擦的分享功能，这正是你获取粉丝的方式（对于新手来说，其他平台更难实现增长）</li><li>你甚至可以直接截屏你的推文来在其他平台上实现增长（这就是我在不花几个小时创建新内容的情况下实现增长的方法）。</li></ul><p>在Twitter上实现增长的基础很简单。</p><ul><li>每天发布1-3次（尽早把你必经的“失败”抛在脑后）</li><li>如果你的粉丝不到1000人，就把重点放在回复和私信中与他人建立网络，借此来撬动<em>他们</em>受众的杠杆。</li><li>用一张<em>让人想点击</em>的头像，好让大家知道你是个创作者</li><li>把你人生的大目标或者你谈论的兴趣作为你的个人简介（你想引导人们走向何处？他们如何通过你独特的兴趣到达那里？）</li><li>根据你的故事和个人经历来写连击推或长帖（但确保你有一个会帮你分享的网络，让它能够半病毒式传播）</li></ul><p>从入门级的教育内容开始。</p><p>让它具有可操作性。</p><p>每个人在刚开始（在任何平台上）寻求增长时都是这么做的，而且95%的市场受众都是新手。</p><p>在你打响名气之前，别试图显得极其聪明或睿智。</p><p><strong>2)</strong> <strong>优先考虑</strong> <strong>想法与注意力捕获</strong></p><p>注意力是21世纪的货币。</p><p>有影响力的想法是你吸引注意力的方式。</p><p>我能给你最好的建议是，以创作者的视角来阅读他人的内容。</p><p>为什么他们的帖子表现好？是什么吸引了你的注意？为什么它有这么高的互动率？</p><p>答案并不总是显而易见的。</p><p>作者们通常有很高的互动率，因为人们已经了解他们的想法。当然，他们仍然是伟大的作家，值得学习。</p><p>在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学 (Digital Economics)</a> 里，我们深入探讨了捕获注意力的心理学，但这里有几个原则，好让你现在就能开始用。</p><p><strong>问题</strong> ——每一个好故事在捕获注意力时，都是从读者面临的一个问题开始的。它开启了一个好奇心循环，让他们想要寻找解决方案。问题是人类行为的根源。</p><p><strong>数字</strong> ——当你在社交媒体上滑动时，具体的数字是一种模式中断。比如：“我读了347本自助书，这样你就不用读了”，这就是个例子。</p><p><strong>统计数据</strong> ——与数字类似，统计数据能很好地设定场景。比如：“97%的人专注力都在下降，这是修复你专注力的方法”。这个例子虽然还可以润色，但你能看到其中的威力。</p><p><strong>3) 把自己当成理想的读者</strong></p><p>当有人在为他们创造的价值建立读者群或受众群体时，普遍的建议是为你理想的客户而写。</p><p>但在一人企业里，<em>你</em>就是你的细分领域。你就是你的客户画像。你就是你的品牌、内容和产品。</p><p>在“数字经济学”里，我让大家做 <a href="https://www.16personalities.com/" target="_blank" rel="noreferrer">MBTI性格测试 (Myers-Briggs personality test)</a>，这样他们就能更多地了解自己。当你了解自己，你就能为自己写作。测试结果就是你的客户画像。</p><p>那么，你该写什么呢？</p><ul><li>如果你正经历低谷，给自己提供建议，并把它写在网上的“公开日记”里</li><li>给过去的自己提供建议，告诉他如何克服你曾经面临的问题，而且要更快地解决</li><li>给未来的自己鼓劲，去实现你正在努力实现的目标。</li></ul><p>这只是你众多创作内容方式中的区区几种，但它们是一个很棒（且触手可及）的起点。</p><p><strong>4) 将你的个人项目转化为产品</strong></p><p>如果你没有朝着自己的目标前进（在任何领域，哪怕建立个人品牌就是你的目标，也要把它写下来），你就没有任何东西可写。</p><p>目标 = 你正在推进的项目。</p><p>当你取得成果时，你就会开始明白是什么带来了这些成果。</p><p>这就是能够盈利的产品或服务的基础。</p><p>如果你已经建立了一家企业，就通过咨询服务或数字产品教人们如何做到这一点。</p><p>如果你已经练出了好身材，也照样做。</p><p>如果你已经塑造了强大的心智，也照样做。</p><p>教人们你是如何获得他们想要的结果的。这并没有那么难。</p><p>你必须研究别人的产品或服务，看看他们是如何构建这些产品或服务的。这是在新社会购买课程的另一个额外好处。</p><p>重申一下，如果你想得到一份工作，那就去购买那些把你训练成员工的昂贵教育。</p><p>如果你想成为一名创作者，那就从那些构成创作者经济的人那里购买教育。</p><p>我已经在<a href="/letters/the-best-online-business-model-to-make-1-million-in-2023">这封信中</a>讨论过首先应该销售什么类型的产品。</p><p>你也可以在 YouTube 上一口气观看/收听<a href="https://youtube.com/playlist?list=PLB4ePXk6nBaeG3fD13NaRMsRsEc2iCsV4" target="_blank" rel="noreferrer">一人企业播放列表（One Person Business Playlist）</a>。</p><p>祝创作愉快。</p><p>– Dan Koe</p><hr><p><a href="/en/letters/the-value-creator-a-new-internet-career-path-for-intelligent-people">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',248))])}const w=a(c,[["render",u]]);export{T as __pageData,w as default};
